INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁钰", "aliases": ["明景帝"], "era": "明", "birth_year": null, "death_year": null, "description": "明景帝，正統14年（1449年）九月，朱祁钰即皇帝位。", "biography": null, "status": "draft", "id": "beac1b51-89b3-5024-bf3a-2d45bc5afe2b"}, {"name": "刘广衡", "aliases": ["劉廣衡"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，天顺元年（年号对照1457年）八月，刘广衡出任刑部尚书。", "biography": null, "status": "draft", "id": "e8cc928c-92be-569b-86b3-362f592a460d"}, {"name": "金濂", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统8年（年号对照1443年）八月，金濂出任刑部尚书。", "biography": null, "status": "draft", "id": "e4b9412a-f029-52ba-ad89-e4b00c73df24"}, {"name": "朱见深", "aliases": ["明宪宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宪宗，天順8年（1464年）正月，朱见深即皇帝位。", "biography": null, "status": "draft", "id": "71fde383-1de5-538d-bb25-2cc9e4cc7d1c"}, {"name": "朱见济", "aliases": ["懷獻太子"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见济获立为皇太子。", "biography": null, "status": "draft", "id": "7f573a8b-cd4b-5a6e-a3ee-4de70f6bc670"}, {"name": "汪氏（明景帝贞惠安和景皇后）", "aliases": ["郕王妃汪氏", "景帝汪皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "汪氏（明景帝贞惠安和景皇后）被立为皇后。", "biography": null, "status": "draft", "id": "e6dd358d-26d5-518b-952f-0d84b504fd0c"}, {"name": "杭氏（明景帝肃孝皇后）", "aliases": ["景帝杭皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "杭氏（明景帝肃孝皇后）获立为皇后。", "biography": null, "status": "draft", "id": "0ea826ff-d313-57cd-82c8-8bd110c3d720"}, {"name": "朱见潾", "aliases": ["朱见清", "榮王", "德莊王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见潾受封荣王。", "biography": null, "status": "draft", "id": "7b3ab777-130c-52de-adb1-5af62c3c97b3"}, {"name": "朱见淳", "aliases": ["許悼王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱见淳受封许王。", "biography": null, "status": "draft", "id": "1fd7ac75-f7e6-5b87-b64e-c51e8d11fcf6"}, {"name": "王翱", "aliases": ["王翺"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰3年（年号对照1452年）二月，王翱结束陕西巡抚职务，返回都察院。", "biography": null, "status": "draft", "id": "285fc3e7-4cbc-5d1a-bb90-b79c366ef275"}, {"name": "王一宁", "aliases": ["王一寧"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰2年（1451年）十二月，王一宁以礼部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "f6c6074a-4339-53a4-ad95-234af53b8770"}, {"name": "王文（明代内阁大学士）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰3年（1452年）十月，王文以太子太保、左都御史身份入阁。", "biography": null, "status": "draft", "id": "0c5a5869-dc9f-5893-b3a4-cbe279406582"}, {"name": "孙镗（明代怀宁侯）", "aliases": ["都督孫鏜"], "era": "明", "birth_year": null, "death_year": null, "description": "孙镗（明代怀宁侯）奉命协守大同。", "biography": null, "status": "draft", "id": "398dbeeb-49de-5e59-83a3-d34743d70b6e"}, {"name": "石彪", "aliases": ["遊擊將軍石彪"], "era": "明", "birth_year": null, "death_year": null, "description": "石彪奉命巡视边防。", "biography": null, "status": "draft", "id": "b3dd53cf-1dfa-5406-ba6a-f6de1d1bab3d"}, {"name": "也先", "aliases": ["瓦剌太师也先"], "era": "明", "birth_year": null, "death_year": null, "description": "也先所部为明廷防备对象。", "biography": null, "status": "draft", "id": "d9af0d41-e6b4-5de2-9de3-32e0f8826f3c"}, {"name": "方瑛", "aliases": ["參將方瑛"], "era": "明", "birth_year": null, "death_year": null, "description": "方瑛参与贵州战事。", "biography": null, "status": "draft", "id": "02981879-a0e2-5f34-81d2-beadecd41264"}, {"name": "于谦", "aliases": ["于謙"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，正统14年（年号对照1449年）八月，于谦出任兵部尚书。", "biography": null, "status": "draft", "id": "3f189404-652f-5b32-9509-a7b9157c87b2"}, {"name": "石亨", "aliases": ["都督石亨"], "era": "明", "birth_year": null, "death_year": null, "description": "石亨奉命统领京营兵。", "biography": null, "status": "draft", "id": "9892b251-a863-5d74-9c23-727ee42a25de"}, {"name": "刘永诚", "aliases": ["太監劉永誠"], "era": "明", "birth_year": null, "death_year": null, "description": "刘永诚参与节制团营。", "biography": null, "status": "draft", "id": "94343797-9a14-5fbc-86d1-7c3f5447fba4"}, {"name": "曹吉祥", "aliases": ["太監曹吉祥"], "era": "明", "birth_year": null, "death_year": null, "description": "曹吉祥参与节制团营。", "biography": null, "status": "draft", "id": "317dfea3-6884-5ef9-82ae-6040eb5025fe"}, {"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "江渊", "aliases": ["江淵"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，景泰元年（1450年）八月，江渊以刑部侍郎兼翰林学士身份入阁。", "biography": null, "status": "draft", "id": "4c319c1c-fb8c-52d1-82ca-fd1b4cdab14e"}]'::jsonb)
