INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明景帝在南郊祭祀天地", "description": "景泰三年正月丙午，明景帝朱祁钰在南郊举行祭祀天地的大典。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年正月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "53b2c704-cfa4-50c1-8c32-3416b64fa343"}, {"title": "刘广衡奉命复核南京囚案", "description": "景泰三年二月乙酉，副都御史刘广衡奉命复核南京在押人员的案件。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年二月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "25063eba-5091-560d-81b2-6fb920e534d9"}, {"title": "金濂被投入监狱，不久获释，被撤去太子太保职衔，改调工部尚书", "description": "景泰3年（年号对照1452年）二月，金濂被投入监狱，不久获释，被撤去太子太保职衔，改调工部尚书。", "start_year": 1452, "end_year": 1452, "time_original": "景泰3年（年号对照1452年）二月；公元年核为1452年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "3f9a8631-675e-581a-bf5e-dcde3f8a9e0f"}, {"title": "毛福寿在湖广巴马击败起事苗民", "description": "景泰三年三月戊午，毛福寿率军征讨湖广巴马起事的苗民，取得胜利。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年三月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a619d966-0ccb-5e8d-8af1-9d12d3ea0798"}, {"title": "明景帝废皇太子朱见深为沂王", "description": "景泰三年五月甲午，明景帝朱祁钰废去朱见深的皇太子身份，改封他为沂王。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94d0abc9-e10e-51d4-85fa-aa77f04aada5"}, {"title": "明景帝立皇子朱见济为皇太子", "description": "景泰三年五月甲午，明景帝朱祁钰废朱见深后，改立自己的儿子朱见济为皇太子。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "753abdb8-156c-57c7-a0d8-d31c98d378e4"}, {"title": "明景帝废皇后汪氏", "description": "景泰三年五月甲午，明景帝朱祁钰废去汪氏的皇后身份。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2f255bd5-3328-5109-90fd-1443f744b9a3"}, {"title": "明景帝立朱见济生母杭氏为皇后", "description": "景泰三年五月甲午，明景帝朱祁钰立皇太子朱见济的生母杭氏为皇后。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c2f1b27-8e6e-5b7b-9775-2d275aaaf7dc"}, {"title": "太上皇之子朱见清受封荣王", "description": "景泰三年五月甲午，明廷封太上皇朱祁镇的儿子朱见清为荣王。《诸王传》记朱见清后来改名朱见潾。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e27d89a9-0642-5833-bb29-67ce46dc0838"}, {"title": "太上皇之子朱见淳受封许王", "description": "景泰三年五月甲午，明廷封太上皇朱祁镇的儿子朱见淳为许王。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba87fbb3-1e00-5f7e-bc30-ba8eb5fdf5db"}, {"title": "明廷在易储后大赦天下", "description": "景泰三年五月甲午，明廷在改立皇太子、皇后及册封亲王后颁布大赦。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "12e5b5b3-c714-5f7d-9f90-899fb693fe5f"}, {"title": "沙湾堤坝修筑完成", "description": "景泰三年五月丙申，沙湾的堤坝修筑完成。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64b71282-d168-5412-953a-607e0288b599"}, {"title": "明廷向回乡复业的河南流民给粮五年", "description": "景泰三年五月辛丑，明廷下令根据人口，向返回原籍恢复生计的河南流民供应五年口粮。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f643c998-0da4-54fc-9ab9-3eced321888c"}, {"title": "明廷各授颜氏和孟氏一名后人官职", "description": "景泰三年五月乙巳，明廷授予颜氏和孟氏各一名后人官职。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年五月乙巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33f7eff0-8be2-581c-b086-3d039ca84a61"}, {"title": "明廷停止各省巡抚入京议事", "description": "景泰三年六月乙亥，朝廷停止各省巡抚官入京议事。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年六月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9b29ed2b-2df4-5fd6-ba46-0e3562c19ed7"}, {"title": "大雨，黄河在沙湾决口", "description": "景泰三年六月，本纪记下了大雨以及黄河在沙湾决口。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c1f105b2-d646-5685-86cc-63f3f76ce715"}, {"title": "王翱出外总督两广", "description": "景泰3年（年号对照1452年）七月，王翱出外总督两广。", "start_year": 1452, "end_year": 1452, "time_original": "景泰3年（年号对照1452年）七月；公元年核为1452年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "859c3686-afc6-557a-8ba5-93f3f749dbaf"}, {"title": "王一宁去世", "description": "景泰3年（1452年）七月，王一宁去世。", "start_year": 1452, "end_year": 1452, "time_original": "景泰3年（1452年）七月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "aa78d634-58a7-5b94-82a6-2698bfc40042"}, {"title": "明廷赈济徐州、兖州水灾", "description": "景泰三年八月乙丑，明廷赈济徐州、兖州的水灾灾区。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年八月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f46c538c-24da-5b45-8945-c3df59841e4c"}, {"title": "明廷派洪英、孙原贞等分赴各地考察官吏", "description": "景泰三年八月戊辰，明廷派都御史洪英、尚书孙原贞、薛希琏等分赴各地考察官吏。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年八月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c671e663-aef9-5e42-a3fd-052d406923d5"}, {"title": "明廷赈济南北直隶水灾州县并免除税粮", "description": "景泰三年八月丁丑，明廷赈济南北直隶遭遇水灾的州县，免除相应税粮。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年八月丁丑", "dynast