location_modern_name": null, "location_note": null, "status": "draft", "id": "d4279280-60e4-5e16-9afc-8323117d4622"}, {"title": "王文以太子太保、左都御史身份入阁", "description": "景泰3年（1452年）十月，王文以太子太保、左都御史身份入阁。", "start_year": 1452, "end_year": 1452, "time_original": "景泰3年（1452年）十月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "a9330389-06d2-5d87-90bb-ddd353f7f4fd"}, {"title": "孙镗、石彪等分别协守大同和宣府", "description": "景泰三年十月丙辰，明廷命都督孙镗、佥事石彪协守大同，并由都督同知卫颍、佥事杨能与张钦协守宣府，防备也先所部。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年十月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "60e56d69-a3e0-50b4-a350-88545974385b"}, {"title": "本纪记景泰三年十一月初一发生日食", "description": "景泰三年十一月初一，本纪记发生日食。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年十一月己未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3975215b-7dbc-514c-8521-65e1ceff8f6b"}, {"title": "方瑛平定白石崖一带的起事", "description": "景泰三年十一月戊辰，都督方瑛率明军平定白石崖一带起事的苗民。", "start_year": 1452, "end_year": 1452, "time_original": "景泰三年十一月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a52695f5-a6d3-5e21-a2c5-9bead7518138"}, {"title": "明廷安置京畿、山东、山西逃民，免赋役五年", "description": "景泰三年十一月甲戌，明廷命人安置京畿、山东、山西的逃民，并免除他们五年赋役。", "start_year": 1453, "end_year": 1453, "time_original": "景泰三年十一月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ec58844b-e0fc-5836-8f51-7e0a33968b80"}, {"title": "明廷豁免山东及淮徐水灾地区税粮", "description": "景泰三年十一月，明廷免除山东和淮安、徐州遭水灾地区应缴的税粮。 按原历纪年，事情发生在公元1452至1453年之间。", "start_year": null, "end_year": null, "time_original": "景泰三年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "709bb78f-20f0-540a-bfb2-001cd5cf89bc"}, {"title": "明廷设立团营，由于谦、石亨等节制", "description": "景泰三年十二月癸巳，明廷开始设立团营，由太监阮让、都督杨俊等分别统领，接受于谦、石亨、刘永诚和曹吉祥的调度。", "start_year": 1453, "end_year": 1453, "time_original": "景泰三年十二月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ed3babc-0c0f-5108-9047-800af2c6e118"}, {"title": "明廷豁免河南、永平灾区秋粮", "description": "景泰三年十二月，明廷免除河南及永平受灾地区应缴的秋粮。", "start_year": 1453, "end_year": 1453, "time_original": "景泰三年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dedf7707-a134-51fe-8795-a49c533a41a5"}, {"title": "本纪汇记景泰三年多地入贡", "description": "景泰三年，瓦剌、琉球中山、爪哇、暹罗、安南、哈密和乌斯藏入贡。 按原历纪年，事情发生在公元1452至1453年之间。", "start_year": null, "end_year": null, "time_original": "景泰三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2dd5e88-bf00-5d34-ad71-77aa7734ef70"}, {"title": "江渊返回原任", "description": "景泰4年（1453年）四月，江渊返回原任。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（1453年）四月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b795f7ef-c88c-5f9f-a8c5-a292edef2